# Le module racine appelle un module enfant
module "reseau" {
  source = "./modules/reseau"      # module local (ou registry / git)
  cidr        = "10.0.0.0/16"     # variables d'ENTRÉE du module
  environment = var.environment
}

# On consomme les OUTPUTS du module
resource "aws_instance" "web" {
  subnet_id = module.reseau.subnet_id   # output exposé par le module
}
